import React,{useEffect,useMemo,useState} from 'react';
import {ArrowDownLeft,ArrowUpRight,ArrowRightLeft,BarChart3,Wallet,BookOpen,ShieldCheck,LogOut,Menu,Bell,Mic,Download,Upload,CheckCircle2,AlertTriangle,Plus,Eye,Trash2,Send,FileText,Users,Landmark,Package,MessageCircle,Settings,Clock3,ChevronRight,Camera,Lock,BriefcaseBusiness,Search} from 'lucide-react';
import logoLight from './assets/tijapass-logo-light-transparent.png';
