function Profile({db,b,commit,notify,lang}){const [checked,setChecked]=useState(b.allowedFIs||[]);const [phone,setPhone]=useState(b.phone||'');const [email,setEmail]=useState(b.email||'');return <div className="stack"><header className="section-head"><h2>{tt(lang,'profile')}</h2><p>{b.name}</p></header><div className="grid-2"><Card title="My business details"><p><b>Owner:</b> {b.owner}</p><p><b>Sector:</b> {b.sector||'Not supplied'}</p><p><b>Identity check:</b> {b.kycApproved?'Verified by TijaPass Admin':'Pending'}</p><p><b>Opening balances:</b> {b.openingApproved?'Approved':'Pending review'}</p><Field label="Contact phone (change request)" value={phone} onChange={setPhone}/><Field label="Email (change request)" value={email} onChange={setEmail}/><Button variant="secondary" onClick={()=>{const n=structuredClone(db);n.tickets.push({id:code('CHANGE'),owner:b.id,message:`Profile correction request: phone ${phone}, email ${email}`,status:'Open',response:''});commit(n);notify('Profile change sent for Admin approval. Your verified details remain unchanged.')}}>Request profile update</Button></Card><Card title="Lender consent"><p>Choose which approved financial institutions may review your credit passport and statements. Consent can be withdrawn here.</p>{db.fIs.filter(f=>f.approved).map(f=><label className="check-row" key={f.id}><input type="checkbox" checked={checked.includes(f.id)} onChange={e=>setChecked(a=>e.target.checked?[...new Set([...a,f.id])]:a.filter(x=>x!==f.id))}/>{f.name}</label>)}<Button onClick={()=>{const n=structuredClone(db);n.businesses.find(x=>x.id===b.id).allowedFIs=checked;commit(n);notify('Lender consent preferences updated.')}}>Save consent choices</Button></Card></div><ExistingLoans db={db} b={b} commit={commit} notify={notify}/></div>}
